import json, sys
from docx import Document
from docx.shared import Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_LINE_SPACING
from docx.enum.style import WD_STYLE_TYPE

doc = Document(sys.argv[1])

ALIGN_MAP = {
    WD_ALIGN_PARAGRAPH.LEFT: "左对齐",
    WD_ALIGN_PARAGRAPH.CENTER: "居中",
    WD_ALIGN_PARAGRAPH.RIGHT: "右对齐",
    WD_ALIGN_PARAGRAPH.JUSTIFY: "两端对齐",
    WD_ALIGN_PARAGRAPH.DISTRIBUTE: "分散对齐",
}
LINE_SPACING_MAP = {
    WD_LINE_SPACING.SINGLE: "单倍行距",
    WD_LINE_SPACING.ONE_POINT_FIVE: "1.5倍行距",
    WD_LINE_SPACING.DOUBLE: "2倍行距",
    WD_LINE_SPACING.AT_LEAST: "最小值",
    WD_LINE_SPACING.EXACTLY: "固定值",
    WD_LINE_SPACING.MULTIPLE: "多倍行距",
}

def has(obj, attr):
    try:
        getattr(obj, attr)
        return True
    except:
        return False

# ---- 1. 页面设置 ----
sections = []
for i, sec in enumerate(doc.sections):
    sections.append({
        "节": i + 1,
        "纸张": f"{sec.page_width.cm:.1f} x {sec.page_height.cm:.1f} cm",
        "上边距": f"{sec.top_margin.cm:.2f} cm",
        "下边距": f"{sec.bottom_margin.cm:.2f} cm",
        "左边距": f"{sec.left_margin.cm:.2f} cm",
        "右边距": f"{sec.right_margin.cm:.2f} cm",
    })

# ---- 2. 样式 ----
styles_list = []
for style in doc.styles:
    if style.type is None:
        continue
    # 只看段落和字符样式
    is_para = (style.type == WD_STYLE_TYPE.PARAGRAPH)
    is_char = (style.type == WD_STYLE_TYPE.CHARACTER)
    if not is_para and not is_char:
        continue

    s = {
        "样式ID": style.style_id,
        "名称": style.name,
        "类型": "段落" if is_para else "字符",
    }
    # base_style
    try:
        s["基于"] = style.base_style.name if style.base_style else "无"
    except:
        s["基于"] = "无"
    # next paragraph (only paragraph styles)
    if is_para:
        try:
            s["后续段落"] = style.next_paragraph_style.name if style.next_paragraph_style else "无"
        except:
            s["后续段落"] = "无"

    # 字体
    fi = {}
    try:
        f = style.font
        if f.name: fi["字体"] = f.name
        if f.size: fi["字号"] = f"{f.size.pt}pt (约{f.size/12700:.1f}号)"
        if f.bold is not None: fi["加粗"] = f.bold
        if f.italic is not None: fi["倾斜"] = f.italic
        if f.color and f.color.rgb: fi["颜色"] = str(f.color.rgb)
    except:
        pass
    if fi: s["字体"] = fi

    # 段落（仅段落样式）
    if is_para:
        pi = {}
        try:
            pf = style.paragraph_format
            if pf.alignment is not None:
                pi["对齐"] = ALIGN_MAP.get(pf.alignment, str(pf.alignment))
            if pf.line_spacing is not None:
                rule = LINE_SPACING_MAP.get(pf.line_spacing_rule, str(pf.line_spacing_rule))
                pi["行距"] = f"{pf.line_spacing:.2f} ({rule})"
            if pf.space_before: pi["段前"] = f"{pf.space_before.pt:.1f}pt"
            if pf.space_after: pi["段后"] = f"{pf.space_after.pt:.1f}pt"
            if pf.first_line_indent:
                pi["首行缩进"] = f"{pf.first_line_indent.pt:.1f}pt ({pf.first_line_indent/360000:.2f}cm)"
            if pf.left_indent: pi["左缩进"] = f"{pf.left_indent.pt:.1f}pt"
            if pf.right_indent: pi["右缩进"] = f"{pf.right_indent.pt:.1f}pt"
        except:
            pass
        if pi: s["段落"] = pi

    if fi or (is_para and "段落" in s):
        styles_list.append(s)

# ---- 3. 段落示例 ----
para_samples = []
for para in doc.paragraphs[:80]:
    text = para.text.strip()
    if not text:
        continue
    fi = {}
    if para.runs:
        r = para.runs[0]
        f = r.font
        if f.name: fi["字体"] = f.name
        if f.size: fi["字号"] = f"{f.size.pt}pt"
        if f.bold: fi["加粗"] = f.bold

    pi = {}
    pf = para.paragraph_format
    if pf.alignment is not None:
        pi["对齐"] = ALIGN_MAP.get(pf.alignment, str(pf.alignment))
    if pf.line_spacing is not None:
        rule = LINE_SPACING_MAP.get(pf.line_spacing_rule, str(pf.line_spacing_rule))
        pi["行距"] = f"{pf.line_spacing:.2f} ({rule})"
    if pf.space_before: pi["段前"] = f"{pf.space_before.pt:.1f}pt"
    if pf.space_after: pi["段后"] = f"{pf.space_after.pt:.1f}pt"
    if pf.first_line_indent:
        pi["首行缩进"] = f"{pf.first_line_indent.pt:.1f}pt ({pf.first_line_indent/360000:.2f}cm)"
    if pf.left_indent: pi["左缩进"] = f"{pf.left_indent.pt:.1f}pt"

    para_samples.append({
        "序号": len(para_samples) + 1,
        "文本(前60字)": text[:60] + ("..." if len(text) > 60 else ""),
        "样式": para.style.name if para.style else "无",
        "字体": fi,
        "段落": pi,
    })

result = {
    "文档信息": {
        "标题": doc.core_properties.title or "",
        "作者": doc.core_properties.author or "",
    },
    "页面设置": sections,
    "样式列表(": len(styles_list),
    "样式": styles_list,
    "段落示例(": len(para_samples),
    "段落": para_samples,
}

with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print(f"OK - {len(styles_list)} styles, {len(para_samples)} paragraphs")

